INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (9, 'Jahitan coverstitch tidak terbentuk dengan benar', 'Jahitan atas atau bawah tidak terbentuk dengan pola yang semestinya atau hasil jahitan tidak stabil.', 'Pemasangan benang tidak tepat, jarum tidak sesuai, atau penyetelan mekanisme coverstitch kurang tepat.', 'Periksa jalur benang, pemasangan jarum UY128GAS, dan penyetelan mesin. Pastikan jenis benang serta jarum sesuai dengan material.', 'Matikan mesin sebelum memasang jarum atau melakukan penyetelan pada mekanisme jahit.', 'Data spesifikasi JUKI MF-7500-U11 dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (9, 'Benang jarum sering putus', 'Benang putus selama proses jahit atau jahitan berhenti sebelum selesai.', 'Jarum rusak atau tidak sesuai, jalur benang kurang tepat, tegangan benang terlalu tinggi, atau ujung jarum mengalami gesekan berlebihan.', 'Periksa jarum UY128GAS dan jalur benang. Sesuaikan tegangan benang dengan material dan kondisi jahitan.', 'Matikan mesin sebelum mengganti jarum atau menyetel tegangan benang.', 'Data spesifikasi needle UY128GAS JUKI MF-7500-U11');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (9, 'Jahitan mengerut atau bergelombang', 'Hasil jahitan pada kain knitwear mengerut, bergelombang, atau tidak rata.', 'Differential feed tidak sesuai dengan karakteristik material atau stitch pitch tidak tepat.', 'Sesuaikan differential feed pada rentang yang tersedia dan atur stitch pitch secara bertahap sampai hasil jahitan stabil.', 'Lakukan penyetelan saat mesin berhenti dan jauhkan tangan dari area jarum.', 'Data spesifikasi differential feed dan stitch pitch JUKI MF-7500-U11');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (9, 'Panjang jahitan tidak sesuai', 'Panjang stitch hasil jahitan berbeda dari pengaturan yang diinginkan.', 'Stitch pitch adjustment tidak tepat atau mekanisme pengaturan stitch mengalami gangguan.', 'Periksa stitch pitch adjustment dan lakukan penyetelan bertahap. Rentang stitch length mesin adalah 1,2–3,6 mm.', 'Matikan mesin sebelum memeriksa mekanisme pengaturan stitch.', 'Data spesifikasi stitch length JUKI MF-7500-U11');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (9, 'Kain tertarik atau feed tidak stabil', 'Material tidak bergerak stabil, tertarik, atau hasil jahitan bergeser.', 'Differential feed, feed dog inclination, atau tekanan presser foot tidak sesuai dengan material.', 'Periksa differential feed dan feed dog inclination. Gunakan micro-lifter dengan penyetelan yang sesuai bila diperlukan.', 'Matikan mesin sebelum melakukan penyetelan mekanisme feed.', 'Data spesifikasi feed dog inclination, differential feed, dan micro-lifter JUKI MF-7500-U11');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (9, 'Jarum patah atau posisi jarum tidak normal', 'Jarum bengkok, patah, atau gerak jarum tidak normal saat menjahit.', 'Jarum tidak terpasang benar, ukuran jarum tidak sesuai, atau needle bar mengalami gangguan.', 'Periksa pemasangan dan kondisi jarum UY128GAS. Periksa needle bar dan gunakan ukuran jarum dalam rentang yang sesuai.', 'Matikan mesin dan lepaskan sumber listrik sebelum mengganti jarum atau memeriksa needle bar.', 'Data spesifikasi needle dan needle bar stroke JUKI MF-7500-U11');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (9, 'Pelumasan tidak normal', 'Gerakan mesin terasa kasar, suara mekanis meningkat, atau bagian bergerak tidak bekerja dengan lancar.', 'Sistem pelumasan otomatis tidak bekerja normal atau level oli tidak sesuai.', 'Periksa sistem automatic lubrication, cartridge oil filter, dan ketersediaan oli. Gunakan JUKI Machine Oil 18 / ISO VG18 sesuai spesifikasi.', 'Matikan mesin sebelum memeriksa atau melakukan pengisian oli.', 'Data spesifikasi lubrication JUKI MF-7500-U11');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (9, 'Benang tidak stabil pada area needle tip', 'Benang terasa kering atau aliran benang di sekitar ujung jarum tidak stabil sehingga kualitas jahitan terganggu.', 'Silicon oil tank tidak bekerja normal atau suplai silicon oil tidak mencukupi.', 'Periksa silicon oil tank dan pastikan suplai oli untuk needle tip serta needle thread berjalan dengan baik.', 'Matikan mesin sebelum memeriksa tangki atau jalur silicon oil.', 'Data spesifikasi silicon oil tank JUKI MF-7500-U11');
